<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const includeSecrets=ref(false);const busy=ref(false);const message=ref('');const backups=ref<components['schemas']['BackupInfo'][]>([]);async function load(){backups.value=requireData(await client.GET('/api/admin/backups'))}async function create(){busy.value=true;message.value='';try{const created=requireData(await client.POST('/api/admin/backups',{body:{includeSecrets:includeSecrets.value}}));await load();message.value=`备份 ${created.name} 已创建，可在下方下载。`}catch(cause){message.value=errorMessage(cause)}finally{busy.value=false}}function download(name:string){return `/api/admin/backups/${encodeURIComponent(name)}`}onMounted(async()=>{try{await load()}catch(cause){message.value=errorMessage(cause)}})</script>
<template><PageHeader title="备份与恢复" description="备份包含一致的 SQLite 快照和数据文件。恢复仅在初始化阶段开放。"/><label class="flex gap-2"><input v-model="includeSecrets" type="checkbox">包含密钥（下载文件必须妥善保管）</label><button class="nw-button mt-4" :disabled="busy" @click="create">创建备份</button><p class="mt-3">{{ message }}</p><ul class="mt-6 grid gap-2"><li v-for="backup in backups" :key="backup.name" class="flex items-center justify-between gap-4"><span>{{ backup.name }} · {{ Math.ceil(backup.size/1024) }} KiB</span><a class="nw-button" :href="download(backup.name)" download>下载</a></li></ul></template>
